SELECT

FROM TODAY_HISTORY_ITEM
WHERE LOGIC_DEL = 0

    AND PAGE_ID = #{dto.pageId}


    AND HISTORY_KEY = #{dto.historyKey}


    AND ITEM_TYPE = #{dto.itemType}


    AND ERA_TYPE = #{dto.eraType}


    AND SECTION_TITLE = #{dto.sectionTitle}


    AND EVENT_YEAR = #{dto.eventYear}


    AND SORT_NO = #{dto.sortNo}


    AND ITEM_HASH = #{dto.itemHash}


    AND CONTENT = #{dto.content}

ORDER BY CREATE_TIME DESC

SELECT

FROM TODAY_HISTORY_ITEM
WHERE LOGIC_DEL = 0

    AND ID = #{dto.id}


    AND PAGE_ID = #{dto.pageId}


    AND HISTORY_KEY = #{dto.historyKey}


    AND ITEM_TYPE = #{dto.itemType}


    AND ERA_TYPE = #{dto.eraType}


    AND SECTION_TITLE = #{dto.sectionTitle}


    AND EVENT_YEAR = #{dto.eventYear}


    AND SORT_NO = #{dto.sortNo}


    AND ITEM_HASH = #{dto.itemHash}


    AND CONTENT = #{dto.content}

ORDER BY MODIFY_TIME DESC

SELECT

FROM TODAY_HISTORY_ITEM
WHERE LOGIC_DEL = 0

    AND ID = #{dto.id}


    AND PAGE_ID = #{dto.pageId}


    AND HISTORY_KEY = #{dto.historyKey}


    AND ITEM_TYPE = #{dto.itemType}


    AND ERA_TYPE = #{dto.eraType}


    AND SECTION_TITLE = #{dto.sectionTitle}


    AND EVENT_YEAR = #{dto.eventYear}


    AND SORT_NO = #{dto.sortNo}


    AND ITEM_HASH = #{dto.itemHash}


    AND CONTENT = #{dto.content}

LIMIT 1
